        ,max(case when local_date = date_add(${local_date}, -3) then 1 else 0 end) as imp_a3
        ,max(case when local_date = date_add(${local_date}, -7) then 1 else 0 end) as imp_a7
        ,max(case when local_date = date_add(${local_date}, -14)  then 1 else 0 end) as imp_a14
